const original = $('Sample Text').first().json.text;
const p = $('Protect').first().json;
const s = $('Reveal String Map').first().json;
const r = $input.first().json;
const fail = (m) => { throw new Error('Round trip: ' + m); };
if (typeof p.protectedText !== 'string') fail('no protectedText');
if (p.protectedText.includes('ana.kovac@example.com')) fail('email still in protectedText');
if (p.protectedText.includes('Janez Novak')) fail('name still in protectedText');
if (!/\[EMAIL_ADDRESS_[a-z0-9]{5}\]/.test(p.protectedText)) fail('no random email placeholder: ' + p.protectedText);
if (!Array.isArray(p.entities) || p.entities.length < 2) fail('expected at least 2 entities');
for (const e of p.entities) {
  if (p.protectedText.slice(e.start, e.end) !== e.placeholder) fail('entity offsets do not point at ' + e.placeholder);
}
if (Object.keys(p.placeholderMap).length < 2) fail('placeholderMap too small');
if ('entityFilterIgnored' in p) fail('entityFilterIgnored present without a filter');
if (r.revealedText !== original) fail('Reveal did not restore the original text');
if (r.unresolvedPlaceholders.length !== 0) fail('unresolved: ' + r.unresolvedPlaceholders.join(', '));
if (s.revealedText !== original) fail('Reveal String Map did not restore the original text');
if (s.protectedText !== p.protectedText) fail('Include Input Fields did not copy the input item');
return [{ json: { check: 'round trip', ok: true, entities: p.entities.length, protectedText: p.protectedText } }];

const original = $('Sample Text').first().json.text;
const p = $('Protect Selected').first().json;
const r = $('Reveal From ID File').first().json;
const c = $input.first().json;
const fail = (m) => { throw new Error('Selected: ' + m); };
if (p.text !== original) fail('Include Input Fields did not copy the text field');
if (!p.protectedText.includes('[EMAIL_ADDRESS_1]')) fail('no sequential email placeholder: ' + p.protectedText);
if (p.placeholderMap.EMAIL_ADDRESS_1 !== 'ana.kovac@example.com') fail('map does not hold EMAIL_ADDRESS_1');
if (p.entities.some((e) => !['PERSON', 'EMAIL_ADDRESS'].includes(e.entityType))) fail('entity outside the selection: ' + JSON.stringify(p.entities));
if (!p.idFile || p.idFile.format !== 'anonymizator-id-file' || p.idFile.version !== 1) fail('idFile missing or wrong format');
if (p.idFile.numbering !== 'sequential') fail('idFile numbering is ' + p.idFile.numbering);
if (r.revealedText !== original) fail('Reveal From ID File did not restore the original text');
if (!c.protectedText.startsWith('Copy [EMAIL_ADDRESS_1] and [EMAIL_ADDRESS_2] ')) fail('continued map did not reuse/continue: ' + c.protectedText);
if (c.placeholderMap.EMAIL_ADDRESS_2 !== 'petra.zupan@example.com') fail('continued map lacks EMAIL_ADDRESS_2');
if (c.placeholderMap.EMAIL_ADDRESS_1 !== 'ana.kovac@example.com') fail('continued map lost EMAIL_ADDRESS_1');
return [{ json: { check: 'selected + sequential + id file + continue', ok: true, protectedText: p.protectedText, continued: c.protectedText } }];

const p = $('Protect Typed').first().json;
const r = $input.first().json;
const fail = (m) => { throw new Error('Typed: ' + m); };
if (Object.keys(p.placeholderMap).length !== 0) fail('typed style must return an empty map');
if ('idFile' in p) fail('typed style must not return an idFile');
if (!p.protectedText.includes('[EMAIL_ADDRESS]')) fail('no [EMAIL_ADDRESS] mask: ' + p.protectedText);
if (p.protectedText.includes('ana.kovac@example.com')) fail('email still present');
if (r.revealedText !== p.protectedText) fail('reveal with an empty map changed the text');
if (!r.unresolvedPlaceholders.includes('[EMAIL_ADDRESS]')) fail('masks not listed as unresolved');
return [{ json: { check: 'typed', ok: true, protectedText: p.protectedText } }];

return [
  { json: { text: 'Hello, my email is ana.kovac@example.com and I need help.' } },
  { json: { text: 'Please write back to ana.kovac@example.com or petra.zupan@example.com.' } },
];

const items = $input.all().map((i) => i.json);
const fail = (m) => { throw new Error('Shared: ' + m); };
if (items.length !== 2) fail('expected 2 items, got ' + items.length);
const key = (m) => Object.keys(m).find((k) => m[k] === 'ana.kovac@example.com');
const k1 = key(items[0].placeholderMap);
const k2 = key(items[1].placeholderMap);
if (!k1 || k1 !== k2) fail('the same email got different placeholders: ' + k1 + ' / ' + k2);
if (!items[1].protectedText.includes('[' + k1 + ']')) fail('second item does not use ' + k1);
if (Object.keys(items[1].placeholderMap).length !== 2) fail('second map should hold both emails');
return [{ json: { check: 'shared map', ok: true, placeholder: k1 } }];

const original = $('Sample Text').first().json.text;
const d = $('Detect').first().json;
const p = $input.first().json;
const fail = (m) => { throw new Error('Detect: ' + m); };
if (d.hasPersonalData !== true) fail('hasPersonalData is not true');
if (d.text !== original) fail('Include Input Fields did not copy the text field');
if (d.countsByType.EMAIL_ADDRESS !== 1) fail('expected one email: ' + JSON.stringify(d.countsByType));
if (d.entityCount !== d.entities.length) fail('entityCount does not match entities');
const total = Object.values(d.countsByType).reduce((a, b) => a + b, 0);
if (total !== d.entityCount) fail('countsByType does not add up');
for (const e of d.entities) {
  if (!['PERSON', 'EMAIL_ADDRESS'].includes(e.entityType)) fail('type outside the selection: ' + e.entityType);
  if (original.slice(e.start, e.end) !== e.value) fail('offsets do not slice the value of ' + e.entityType);
}
if (d.entities.some((e) => e.value === 'Janez Novak')) fail('the ignored name was reported');
if ('placeholderMap' in p) fail('Include Placeholder Map off still output placeholderMap');
if ('idFile' in p) fail('Include Placeholder Map off output an idFile');
if (p.protectedText.includes('Janez Novak')) fail('name still in protectedText');
if (!p.protectedText.includes('ana.kovac@example.com')) fail('the ignored email was replaced');
if (!/\[PERSON_[a-z0-9]{5}\]/.test(p.protectedText)) fail('no random person placeholder: ' + p.protectedText);
if (JSON.stringify(p).includes('Janez Novak')) fail('a protected value is in the output');
return [{ json: { ok: true, countsByType: d.countsByType, protectedText: p.protectedText } }];
